def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_d = my.count('D')

    if opp_d > n * 0.5:
        return 'D'

    if opp_d == 0 and n > 20:
        return 'D'

    if opp[-1] == 'D':
        if n >= 2 and opp[-2] == 'D':
            return 'D' if rng.random() < 0.9 else 'C'
        if len(my) >= 3 and 'D' in my[-3:]:
            return 'C' if rng.random() < 0.8 else 'D'
        return 'D' if rng.random() < 0.8 else 'C'

    if my[-1] == 'D':
        return 'C'

    if my_d < 9:
        if my_d == 0 and n == 10:
            return 'D'
        if my_d > 0:
            retaliations = 0
            for i in range(n - 1):
                if my[i] == 'D' and opp[i+1] == 'D':
                    retaliations += 1
            ret_rate = retaliations / my_d
            if ret_rate <= 0.3:
                if n >= 10 and (n - 10) % 6 == 0:
                    return 'D'
    return 'C'
